e_point":26753.56,"total_kgco2e_min":24997.61,"total_kgco2e_max":28509.51,"g_co2e_per_km_point":178.36,"diff_vs_icev_pct":-8.43}],"engineering_interpretation":"Lower-intensity cell manufacturing reduces 40 kWh BEV upfront manufacturing emissions to ~2,500 kg CO2e for the pack, accelerating carbon break-even vs ICEV."},{"case_id":"SENS-BAT-HIGH","dimension":"Battery Pack Manufacturing Intensity","scenario_label":"Higher-Carbon Coal-Grid Cell Mfg (95–130 kg CO2e/kWh)","parameter_description":"40 kWh BEV pack @ 95–130 kg CO2e/kWh (Midpoint: 112.5 kg CO2e/kWh)","results_by_powertrain":[{"code":"ICEV","total_kgco2e_point":29215.63,"total_kgco2e_min":27515.19,"total_kgco2e_max":30916.07,"g_co2e_per_km_point":194.77,"diff_vs_icev_pct":0},{"code":"HEV","total_kgco2e_point":23150.47,"total_kgco2e_min":21483.74,"total_kgco2e_max":24817.2,"g_co2e_per_km_point":154.34,"diff_vs_icev_pct":-20.76},{"code":"BEV","total_kgco2e_point":26966.27,"total_kgco2e_min":24841.24,"total_kgco2e_max":29091.3,"g_co2e_per_km_point":179.78,"diff_vs_icev_pct":-7.7},{"code":"CNG","total_kgco2e_point":26753.56,"total_kgco2e_min":24997.61,"total_kgco2e_max":28509.51,"g_co2e_per_km_point":178.36,"diff_vs_icev_pct":-8.43}],"engineering_interpretation":"Energy-intensive cell manufacturing adds +2,000 kg CO2e to the 40 kWh BEV pack, delaying the break-even distance against ICEV by ~35,000 km."}]', '2026-10-18 12:37:29');
