},{"case_id":"SENS-DIST-250K","dimension":"Lifetime Distance (Functional Unit)","scenario_label":"High / Fleet Utilisation (250,000 km)","parameter_description":"Functional unit = 250,000 vehicle-km (assuming single battery pack lifetime)","results_by_powertrain":[{"code":"ICEV","total_kgco2e_point":44837.25,"total_kgco2e_min":42823.29,"total_kgco2e_max":46851.2,"g_co2e_per_km_point":179.35,"diff_vs_icev_pct":0},{"code":"HEV","total_kgco2e_point":34438.8,"total_kgco2e_min":32544.63,"total_kgco2e_max":36332.98,"g_co2e_per_km_point":137.76,"diff_vs_icev_pct":-23.19},{"code":"BEV","total_kgco2e_point":36792.67,"total_kgco2e_min":34667.64,"total_kgco2e_max":38917.7,"g_co2e_per_km_point":147.17,"diff_vs_icev_pct":-17.94},{"code":"CNG","total_kgco2e_point":40599.71,"total_kgco2e_min":38516.84,"total_kgco2e_max":42682.59,"g_co2e_per_km_point":162.4,"diff_vs_icev_pct":-9.45}],"engineering_interpretation":"High-mileage commercial/fleet utilisation maximises operational fuel-saving benefits for BEV and HEV, provided traction battery replacement is not triggered."},{"case_id":"SENS-REC-PRIMARY","dimension":"Recycled Material Shares","scenario_label":"0% Recycled Metals (100% Primary Virgin Route)","parameter_description":"0% secondary steel & 0% secondary aluminium (uses ~8–18 kg CO2e/kg primary Al band)","results_by_powertrain":[{"code":"ICEV","total_kgco2e_point":29825.2,"total_kgco2e_min":27918.98,"total_kgco2e_max":31731.42,"g_co2e_per_km_point":198.83,"diff_vs_icev_pct":0},{"code":"HEV","total_kgco2e_point":23837.19,"total_kgco2e_min":21922.27,"total_kgco2e_max":25752.12,"g_co2e_per_km_point":158.91,"diff_vs_icev_pct":-20.08},{"code":"BEV","total_kgco2e_point":26639.3,"total_kgco2e_min":24216.75,"total_kgco2e_max":29061.85,"g_co2e_per_km_point":177.6,"diff_vs_icev_pct":-10.68},{"code":"CNG","total_kgco2e_point":27375.14,"total_kgco2e_min":25409.8,"total_kgco2e_max":29340.47,"g_co2e_per_km_point":182.5,"diff_vs_icev_pct":-8.21}],"engineering_interpretation":"Because BEV and HEV contain higher wrought/cast aluminium mass (185 kg in BEV vs 119 kg in ICEV in SWD 2023/256), 100% primary smelting significantly inflates cradle-to-gate material emissions."},{"case_id":"SENS-REC-HIGH","dimension":"Recycled Material Shares","scenario_label":"High Secondary/Recycled Metals (50% Steel / 75% Aluminium)","parameter_description":"50% EAF steel & 75% secondary aluminium (~0.5–2.5 kg CO2e/kg)","results_by_powertrain":[{"code":"ICEV","total_kgco2e_point":28472.33,"total_kgco2e_min":27021.06,"total_kgco2e_max":29923.6,"g_co2e_per_km_point":189.82,"diff_vs_icev_pct":0},{"code":"HEV","total_kgco2e_point":22222.07,"total_kgco2e_min":20853.14,"total_kgco2e_max":23591,"g_co2e_per_km_point":148.15,"diff_vs_icev_pct":-21.95},{"code":"BEV","total_kgco2e_point":24722.67,"total_kgco2e_min":22951.42,"total_kgco2e_max":26493.92,"g_co2e_per_km_point":164.82,"diff_vs_icev_pct":-13.17},{"code":"CNG","total_kgco2e_point":25992.26,"total_kgco2e_min":24490.88,"total_kgco2e_max":27493.64,"g_co2e_per_km_point":173.28,"diff_vs_icev_pct":-8.71}],"engineering_interpretation":"Switching to secondary aluminium (~0.5–2.5 vs ~8–18 kg CO2e/kg) and EAF steel cuts glider cradle-to-gate material footprint by over 1,100 kg CO2e per vehicle."},{"case_id":"SENS-BAT-LOW","dimension":"Battery Pack Manufacturing Intensity","scenario_label":"Lower-Carbon LFP / Clean Cell Mfg (55–70 kg CO2e/kWh)","parameter_description":"40 kWh BEV pack @ 55–70 kg CO2e/kWh (Midpoint: 62.5 kg CO2e/kWh)","results_by_powertrain":[{"code":"ICEV","total_kgco2e_point":29215.63,"total_kgco2e_min":27515.19,"total_kgco2e_max":30916.07,"g_co2e_per_km_point":194.77,"diff_vs_icev_pct":0},{"code":"HEV","total_kgco2e_point":23075.47,"total_kgco2e_min":21423.74,"total_kgco2e_max":24727.2,"g_co2e_per_km_point":153.84,"diff_vs_icev_pct":-21.02},{"code":"BEV","total_kgco2e_point":24966.27,"total_kgco2e_min":23241.24,"total_kgco2e_max":26691.3,"g_co2e_per_km_point":166.44,"diff_vs_icev_pct":-14.54},{"code":"CNG","total_kgco2e_point":26753.56,"total_kgco2e_min":24997.61,"total_kgco2e_max":28509.51,"g_co2e_per_km_point":178.36,"diff_vs_icev_pct":-8.43}],"engineering_interpretation":"Lower-intensity cell manufacturing reduces 40 kWh BEV upfront manufacturing emissions to ~2,500 kg CO2e for the pack, accelerating carbon break-even vs ICEV."},{"case_id":"SENS-BAT-HIGH","dimension":"Battery Pack Manufacturing Intensity","scenario_label":"Higher-Carbon Coal-Grid Cell Mfg (95–130 kg CO2e/kWh)","parameter_description":"40 kWh BEV pack @ 95–130 kg CO2e/kWh (Midpoint: 112.5 kg CO2e/kWh)","results_by_powertrain":[{"code":"ICEV","total_kgco2e_point":29215.63,"total_kgco2e_min":27515.19,"total_kgco2e_max":30916.07,"g_co2e_per_km_point":194.77,"diff_vs_icev_pct":0},{"code":"HEV","total_kgco2e_point":23150.47,"total_kgco2e_min":21483.74,"total_kgco2e_max":24817.2,"g_co2e_per_km_point":154.34,"diff_vs_icev_pct":-20.76},{"code":"BEV","total_kgco2e_point":26966.27,"total_kgco2e_min":24841.24,"total_kgco2e_max":29091.3,"g_co2e_per_km_point":179.78,"diff_vs_icev_pct":-7.7},{"code":"CNG","total_kgco2e_point":26753.56,"total_kgco2e_min":24997.61,"total_kgco2e_max":28509.51,"g_co2e_per_km_point":178.36,"diff_vs_icev_pct":-8.43}],"engineering_interpretation":"Energy-intensive cell manufacturing adds +2,000 kg CO2e to the 40 kWh BEV pack, delaying the break-even distance against ICEV by ~35,000 km."}]', '2026-10-18 13:05:08');

CREATE TABLE component_materials (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      component_id TEXT NOT NULL REFERENCES components(component_id) ON DELETE CASCADE,
      material_id TEXT REFERENCES materials(material_id),
      material_name TEXT NOT NULL,
      mass_kg REAL,
      mass_fraction_pct REAL,
      notes TEXT
    );

