INSERT INTO components (component_id, component_name, component_category, applicable_powertrain, mass_kg, material_composition_json, manufacturing_processes, geography, reference_year, source_id, confidence_status, notes, created_at) VALUES ('COMP-SUB-BIW', 'Body-in-White (BIW) & Body Panels', 'Body & Structural Subsystem', 'All Powertrains', NULL, '[{"material_id":"MAT-STEEL-AUTO","material_name":"Carbon steel / automotive steel","role":"Predominant structural & panel material"},{"material_id":"MAT-ALU-PRIMARY","material_name":"Wrought aluminium","role":"Lightweight hood/closures where applicable"}]', 'Stamping, Welding, Painting', 'Global / Representative', 2026, 'SRC-PACK-2026', 'Qualitative Subsystem Guidance (No exact retail model mass claimed)', 'Section 3: Body-in-white/body panels are predominantly steel. Do not assign generic component percentages to a named model unless source supports it.', '2026-10-19 07:48:34');
INSERT INTO components (component_id, component_name, component_category, applicable_powertrain, mass_kg, material_composition_json, manufacturing_processes, geography, reference_year, source_id, confidence_status, notes, created_at) VALUES ('COMP-SUB-ICE-ENG', 'Internal Combustion Engine (ICE) Assembly', 'Powertrain Subsystem', 'Petrol (ICEV) / Diesel (ICEV) / HEV / PHEV / CNG', NULL, '[{"material_id":"MAT-CAST-IRON","material_name":"Cast iron","role":"Cylinder block, crankshaft, exhaust manifold"},{"material_id":"MAT-STEEL-AUTO","material_name":"Steel","role":"Forged connecting rods, camshafts, valves"},{"material_id":"MAT-ALU-PRIMARY","material_name":"Cast aluminium","role":"Cylinder head, pistons, crankcase"}]', 'Iron casting / iron process, Aluminium shape casting, Forging, Machining', 'Global / Representative', 2026, 'SRC-PACK-2026', 'Qualitative Subsystem Guidance (Requires GREET VMC 2020 extraction for exact kg)', 'Section 3: Engine uses cast iron, steel and aluminium.', '2026-10-19 07:48:34');
INSERT INTO components (component_id, component_name, component_category, applicable_powertrain, mass_kg, material_composition_json, manufacturing_processes, geography, reference_year, source_id, confidence_status, notes, created_at) VALUES ('COMP-SUB-EMOTOR', 'Electric Traction Motor & Inverter', 'Electrified Powertrain Subsystem', 'Battery Electric (BEV) / Full Hybrid (HEV) / Plug-in Hybrid (PHEV) / FCEV', NULL, '[{"material_id":"MAT-STEEL-AUTO","material_name":"Electrical laminated steel","role":"Stator and rotor cores"},{"material_id":"MAT-COPPER","material_name":"Copper","role":"Stator windings and busbars"},{"material_id":"MAT-ALU-PRIMARY","material_name":"Cast aluminium","role":"Motor housing and endbells"}]', 'Stamping, Copper wire production, Aluminium shape casting, Machining', 'Global / Representative', 2026, 'SRC-PACK-2026', 'Qualitative Subsystem Guidance (Requires GREET VMC 2020 extraction for exact kg)', 'Section 3: Electric motor uses steel, copper and aluminium.', '2026-10-19 07:48:34');
INSERT INTO components (component_id, component_name, component_category, applicable_powertrain, mass_kg, material_composition_json, manufacturing_processes, geography, reference_year, source_id, confidence_status, notes, created_at) VALUES ('COMP-SUB-WIRING', 'Wiring Harness & Power Electronics', 'Electrical & Electronics Subsystem', 'All Powertrains (Higher copper mass in BEV/PHEV)', NULL, '[{"material_id":"MAT-COPPER","material_name":"Copper","role":"Low-voltage and high-voltage cables, connectors"},{"material_id":"MAT-PLASTICS-MIXED","material_name":"Plastics (insulation & housings)","role":"Cable insulation, connector housings"}]', 'Copper wire production, Polymer moulding', 'Global / Representative', 2026, 'SRC-PACK-2026', 'Qualitative Subsystem Guidance', 'Section 3: Wiring/electronics use copper, plastics and other metals (BEV copper increases to 35 kg vs 14 kg in ICEV in SWD 2023/256).', '2026-10-19 07:48:34');
INSERT INTO components (component_id, component_name, component_category, applicable_powertrain, mass_kg, material_composition_json, manufacturing_processes, geography, reference_year, source_id, confidence_status, notes, created_at) VALUES ('COMP-SUB-TYRES', 'Tyres & Wheels Subsystem', 'Chassis & Running Gear', 'All Powertrains', NULL, '[{"material_id":"MAT-RUBBER-TYRE","material_name":"Rubber / tyre compounds","role":"Tread, sidewall, inner liner"},{"material_id":"MAT-STEEL-AUTO","material_name":"Steel cord & bead wire","role":"Belt reinforcement and bead"}]', 'Rubber compounding, vulcanisation, steel wire drawing', 'Global / Representative', 2026, 'SRC-PACK-2026', 'Qualitative Subsystem Guidance', 'Section 3: Tyres use rubber, steel and textile.', '2026-10-19 07:48:34');
INSERT INTO components (component_id, component_name, component_category, applicable_powertrain, mass_kg, material_composition_json, manufacturing_processes, geography, reference_year, source_id, confidence_status, notes, created_at) VALUES ('COMP-SUB-BATTERY', 'Traction Battery Pack (LFP / NMC)', 'Energy Storage Subsystem', 'Battery Electric (BEV) / Plug-in Hybrid (PHEV) / Full Hybrid (HEV)', NULL, '[{"material_id":"MAT-LIB-PACK","material_name":"Cathode, Anode, Electrolyte, Separator","role":"Active cell chemistry (LFP, NMC, etc.)"},{"material_id":"MAT-ALU-PRIMARY","material_name":"Aluminium","role":"Cathode current collector foil & pack enclosure"},{"material_id":"MAT-COPPER","material_name":"Copper","role":"Anode current collector foil & busbars"},{"material_id":"MAT-STEEL-AUTO","material_name":"Steel","role":"Protective tray / structural framing"}]', 'Electrode coating, cell assembly, formation, module & pack assembly', 'Global / BatPaC 5.2 Reference', 2025, 'SRC-GREET-BAT-2025', 'Chemistry-Dependent (Requires BatPaC 5.2 / model-specific kWh disclosure)', 'Section 3: Battery composition depends strongly on chemistry (LFP, NMC etc.). Do not treat lithium carbonate factor as whole-battery factor.', '2026-10-19 07:48:34');

CREATE TABLE end_of_life_systems (
      eol_id TEXT PRIMARY KEY,
      system_name TEXT NOT NULL,
      applicable_material_or_vehicle TEXT NOT NULL,
      dismantling_process TEXT NOT NULL,
      recovery_rate_pct REAL,
      recycling_rate_pct REAL,
      process_energy_mj_per_kg REAL,
      process_emissions_kgco2e_per_kg REAL,
      allocation_method TEXT NOT NULL CHECK(allocation_method IN ('Cut-off (Recycled Content)', 'Avoided Burden (End-of-Life Recycling Credit)', '50/50 Allocation', 'System Expansion / Stated in Source')),
      recycling_credit_kgco2e_per_kg REAL,
      geography TEXT NOT NULL,
      reference_year INTEGER,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      data_quality_status TEXT NOT NULL,
      notes TEXT
    );

INSERT INTO end_of_life_systems (eol_id, system_name, applicable_material_or_vehicle, dismantling_process, recovery_rate_pct, recycling_rate_pct, process_energy_mj_per_kg, process_emissions_kgco2e_per_kg, allocation_method, recycling_credit_kgco2e_per_kg, geography, reference_year, source_id, data_quality_status, notes) VALUES ('EOL-ELV-CUTOFF', 'End-of-Life Vehicle (ELV) Dismantling & Shredding — Cut-off Approach', 'All Passenger Vehicles (Glider & Metals)', 'Depollution (fluids, battery, tyres, catalyst removal), dismantling, shredding, magnetic/eddy-current separation', NULL, NULL, NULL, NULL, 'Cut-off (Recycled Content)', 0, 'India / Global Methodological Standard', 2026, 'SRC-PACK-2026', 'Methodological Rule (Section 7)', 'Under Cut-off allocation, secondary materials enter manufacturing with their recycled production factor (e.g. 0.5–2.5 kg CO2e/kg for secondary Al), and no avoided-burden credit is subtracted at EoL to prevent double-counting.');
INSERT INTO end_of_life_systems (eol_id, system_name, applicable_material_or_vehicle, dismantling_process, recovery_rate_pct, recycling_rate_pct, process_energy_mj_per_kg, process_emissions_kgco2e_per_kg, allocation_method, recycling_credit_kgco2e_per_kg, geography, reference_year, source_id, data_quality_status, notes) VALUES ('EOL-ELV-AVOIDED-BURDEN', 'End-of-Life Vehicle (ELV) — Avoided-Burden Recycling Credit Approach', 'Steel, Aluminium, Copper & Traction Battery Metals', 'Dismantling, closed/open-loop scrap recovery and remelting', NULL, NULL, NULL, NULL, 'Avoided Burden (End-of-Life Recycling Credit)', NULL, 'India / Global Methodological Standard', 2026, 'SRC-PACK-2026', 'Methodological Rule (Section 7)', 'Section 7: State whether recycling credits are avoided-burden, cut-off, or another method. Do not apply both high recycled-content input credits and full end-of-life avoided primary metal credits simultaneously.');
INSERT INTO end_of_life_systems (eol_id, system_name, applicable_material_or_vehicle, dismantling_process, recovery_rate_pct, recycling_rate_pct, process_energy_mj_per_kg, process_emissions_kgco2e_per_kg, allocation_method, recycling_credit_kgco2e_per_kg, geography, reference_year, source_id, data_quality_status, notes) VALUES ('EOL-LIB-RECYCLING', 'Lithium-Ion Traction Battery End-of-Life Hydrometallurgical / Pyrometallurgical Recycling', 'Battery Electric (BEV) / PHEV / HEV Traction Battery Pack', 'Pack discharge, disassembly, cell crushing/black mass recovery, hydrometallurgical/pyrometallurgical refining', NULL, NULL, NULL, NULL, 'System Expansion / Stated in Source', NULL, 'India / Global (GREET / Nature 2022)', 2025, 'SRC-GREET-BAT-2025', 'Requires Chemistry-Specific EoL Inventory', 'Section 8 (Archetype 6): Model battery recycling explicitly; recovery value differs sharply between NMC (Co, Ni, Li, Cu) and LFP (Li, Fe, P, Cu, Al).');

CREATE TABLE energy_factors (
      energy_id TEXT PRIMARY KEY,
      carrier TEXT NOT NULL,
      pathway TEXT NOT NULL,
      factor_value REAL,
      factor_min REAL,
      factor_max REAL,
      unit TEXT NOT NULL,
      geography TEXT NOT NULL,
      reference_year TEXT NOT NULL,
      lifecycle_boundary TEXT NOT NULL CHECK(lifecycle_boundary IN ('Tank-to-Wheel (Combustion Only)', 'Well-to-Tank (Upstream Production & Delivery)', 'Well-to-Wheel / Full Lifecycle', 'Generation Grid Mix', 'Cradle-to-Gate H2 Production')),
      factor_type_details TEXT,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      data_quality_status TEXT NOT NULL,
      critical_caveat TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-H2-NG-UNABATED', 'Hydrogen', 'Hydrogen from unabated natural gas (SMR without CCS)', 11, 10, 12, 'kg CO2e/kg H2', 'Global', '2024', 'Cradle-to-Gate H2 Production', 'IEA 2024 Global Production Range (~10–12 kg CO2e/kg H2)', 'SRC-IEA-H2-2024', 'Directly Extracted from PDF (IEA 2024 Range)', 'Global production estimate; upstream/midstream methane leakage and capture boundary matter.', '2026-10-19 07:48:34');
INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-H2-COAL-UNABATED', 'Hydrogen', 'Hydrogen from unabated coal gasification', 24, 22, 26, 'kg CO2e/kg H2', 'Global', '2024', 'Cradle-to-Gate H2 Production', 'IEA 2024 Global Production Range (~22–26 kg CO2e/kg H2)', 'SRC-IEA-H2-2024', 'Directly Extracted from PDF (IEA 2024 Range)', 'Global production estimate; not a universal India-specific value.', '2026-10-19 07:48:34');
INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-H2-ELECTROLYTIC', 'Hydrogen', 'Electrolytic hydrogen (water electrolysis)', NULL, NULL, NULL, 'kg CO2e/kg H2', 'India / Grid-Dependent', '2024-2026', 'Well-to-Tank (Upstream Production & Delivery)', 'Calculated from electricity carbon intensity × electrolyser kWh/kg H2', 'SRC-IEA-H2-2024', 'Formula / Scenario Parameter (Depends on Electricity Factor)', 'Not automatically green; calculate using electricity factor and equipment assumptions.', '2026-10-19 07:48:34');
INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-GRID-INDIA-CEA', 'Grid electricity (India)', 'Indian National Grid Electricity Mix (CEA CDM CO2 Baseline Database)', NULL, NULL, NULL, 'kg CO2/kWh', 'India', 'Requires Fiscal Year (e.g. FY 2022-23 / FY 2023-24)', 'Generation Grid Mix', 'Use latest CEA CO2 Baseline Database; specify weighted-average, operating margin, or combined margin', 'SRC-CEA-INDIA', 'External Official Source Registered — Import Specific CEA FY Version', 'Record fiscal year and whether factor is weighted-average, operating margin, combined margin, etc. Do not assume an older CEA factor is the latest one.', '2026-10-19 07:48:34');
INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-SOLAR-PV', 'Solar PV electricity', 'Utility / Rooftop Solar Photovoltaic Generation', NULL, NULL, NULL, 'kg CO2e/kWh', 'India / Harmonised LCA', '2026', 'Well-to-Wheel / Full Lifecycle', 'Lifecycle kg CO2e/kWh from a harmonised LCA source', 'SRC-PACK-2026', 'Requires Harmonised LCA Dataset Import', 'Include module manufacturing, balance of system, installation and end-of-life; not zero over lifecycle.', '2026-10-19 07:48:34');
