INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-PETROL-TTW', 'Petrol', 'Automotive Petrol — Tailpipe Combustion (Tank-to-Wheel)', NULL, NULL, NULL, 'kg CO2e/L', 'India', '2026', 'Tank-to-Wheel (Combustion Only)', 'Tailpipe combustion factor (separate from upstream refining)', 'SRC-PACK-2026', 'Requires Cited Govt / GHG Inventory Factor Import', 'Keep tailpipe and upstream separate; do not compare combustion-only petrol with lifecycle electricity.', '2026-10-19 07:48:34');
INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-PETROL-WTT', 'Petrol', 'Automotive Petrol — Upstream Extraction, Refining & Distribution (Well-to-Tank)', NULL, NULL, NULL, 'kg CO2e/L', 'India', '2026', 'Well-to-Tank (Upstream Production & Delivery)', 'Upstream extraction/refining/distribution factor', 'SRC-PACK-2026', 'Requires Cited Govt / GHG Inventory Factor Import', 'Combine with Tank-to-Wheel factor for full Well-to-Wheel comparison against BEV.', '2026-10-19 07:48:34');
INSERT INTO energy_factors (energy_id, carrier, pathway, factor_value, factor_min, factor_max, unit, geography, reference_year, lifecycle_boundary, factor_type_details, source_id, data_quality_status, critical_caveat, created_at) VALUES ('NRG-DIESEL-TTW', 'Diesel', 'Automotive Diesel — Tailpipe Combustion (Tank-to-Wheel)', NULL, NULL, NULL, 'kg CO2e/L', 'India', '2026', 'Tank-to-Wheel (Combustion Only)', 'Tailpipe combustion factor (state biodiesel blend assumptions)', 'SRC-PACK-2026', 'Requires Cited Govt / GHG Inventory Factor Import', 'Use a cited government/GHG inventory factor and stated blend assumptions.', '2026-10-19 07:48:34');
