CREATE TABLE environmental_indicators (
      indicator_id TEXT PRIMARY KEY,
      indicator_name TEXT NOT NULL,
      indicator_code TEXT NOT NULL,
      lcia_method TEXT NOT NULL,
      unit TEXT NOT NULL,
      scope_description TEXT NOT NULL,
      status_in_pack TEXT NOT NULL,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      notes TEXT
    );

INSERT INTO environmental_indicators (indicator_id, indicator_name, indicator_code, lcia_method, unit, scope_description, status_in_pack, source_id, notes) VALUES ('IND-GWP100', 'Climate Change — Global Warming Potential (GWP100)', 'GWP100', 'IPCC AR6 / GREET GHG (CO2, CH4, N2O)', 'kg CO2e (and g CO2e/km)', 'Mandatory baseline indicator across all lifecycle modules (materials, manufacturing, fuel/energy pathway, use phase, end-of-life).', 'Active & Populated in Reference Data Pack', 'SRC-PACK-2026', 'Report both total kg CO2e/vehicle and g CO2e/km over declared lifetime (e.g. 150,000 km).');
INSERT INTO environmental_indicators (indicator_id, indicator_name, indicator_code, lcia_method, unit, scope_description, status_in_pack, source_id, notes) VALUES ('IND-WATER', 'Water Use / Scarcity Footprint', 'WCP', 'ReCiPe / AWARE / GREET Water Module (Do not mix methods)', 'm3 or L water consumed', 'Optional indicator: mining/refining, battery material processing, painting, and power generation cooling.', 'Schema Supported — Store Only When Defensible Method-Consistent Data Exist', 'SRC-PACK-2026', 'Section 7: Store only when the chosen LCIA method and data are available; do not mix indicator methods or combine into an unexplained score.');
INSERT INTO environmental_indicators (indicator_id, indicator_name, indicator_code, lcia_method, unit, scope_description, status_in_pack, source_id, notes) VALUES ('IND-RESOURCE', 'Mineral / Resource Depletion (Abiotic Depletion Potential)', 'ADP / SOP', 'CML / ReCiPe (Surplus Ore Potential / kg Sb-eq or kg Cu-eq)', 'kg Sb-eq or kg Cu-eq', 'Optional indicator: critical mineral intensity (lithium, cobalt, nickel, copper, rare earths, platinum group metals).', 'Schema Supported — Store Only When Defensible Method-Consistent Data Exist', 'SRC-PACK-2026', 'Do not combine with GWP into a single weighted score.');
INSERT INTO environmental_indicators (indicator_id, indicator_name, indicator_code, lcia_method, unit, scope_description, status_in_pack, source_id, notes) VALUES ('IND-PM', 'Particulate Matter Formation (PM2.5 / PM10)', 'PMFP', 'ReCiPe / ILCD', 'kg PM2.5-eq', 'Optional indicator: coal power generation, metal smelting, tailpipe exhaust, and non-exhaust brake/tyre/road wear.', 'Schema Supported — Store Only When Defensible Method-Consistent Data Exist', 'SRC-PACK-2026', 'High relevance for Indian urban air quality and coal-heavy industrial processes.');
INSERT INTO environmental_indicators (indicator_id, indicator_name, indicator_code, lcia_method, unit, scope_description, status_in_pack, source_id, notes) VALUES ('IND-AP', 'Terrestrial Acidification Potential', 'AP', 'ReCiPe / CML', 'kg SO2-eq', 'Optional indicator: SOx and NOx emissions from fuel refining, grid power, and smelting (e.g. nickel/copper).', 'Schema Supported — Store Only When Defensible Method-Consistent Data Exist', 'SRC-PACK-2026', 'Store only when chosen LCIA method and data are available.');
INSERT INTO environmental_indicators (indicator_id, indicator_name, indicator_code, lcia_method, unit, scope_description, status_in_pack, source_id, notes) VALUES ('IND-EP', 'Freshwater / Marine Eutrophication Potential', 'EP', 'ReCiPe / CML', 'kg P-eq or kg N-eq', 'Optional indicator: nutrient run-off from biofuel feedstocks, mining tailings, and chemical processing.', 'Schema Supported — Store Only When Defensible Method-Consistent Data Exist', 'SRC-PACK-2026', 'Store only when chosen LCIA method and data are available.');

