INSERT INTO import_reports (report_id, import_source_name, import_type, total_rows_processed, successful_imports, skipped_rows, duplicate_rows, flagged_for_review, details_json, created_at) VALUES ('REP-PDF-INIT-20261018', 'Automotive_LCA_Reference_Data_Pack_2026.pdf', 'PDF Structured Extraction & Seed Pipeline', 75, 75, 0, 0, 9, '{
  "source_document": "Automotive Life-Cycle Assessment Reference Data Pack (18 October 2026)",
  "extracted_sections": [
    "Section 1: Scope & functional unit (150,000 km passenger car, kg CO2e/vehicle and g CO2e/km)",
    "Section 2: 10 Material screening emission factor bands + 2 additional BOM materials from Section 3 (Manganese, GFRP)",
    "Section 3: 4 Complete European SWD(2023) 256 vehicle material compositions (ICEV, HEV, PHEV, BEV; 12 material rows each = 48 BOM entries totaling 1,137 kg/vehicle) + 6 subsystem qualitative mappings",
    "Section 4: 15 Manufacturing process energy & CO2 records from PMC10890010 Table 4 + 1 explicit data-gap warning record for Polymer Injection Moulding",
    "Section 5: 12 Energy carrier & fuel-cycle records (including IEA 2024 Hydrogen ranges: 10–12 kg CO2e/kg H2 for natural gas and 22–26 kg CO2e/kg H2 for coal, plus CEA India Grid & fuel pathway definitions)",
    "Section 6: 4 Transportation & logistics mode layers (Road, Rail, Coastal Shipping, Supplier-to-Plant)",
    "Section 7: 3 Use-phase functional unit profiles, 3 End-of-Life allocation systems, and 6 Environmental Impact Indicators",
    "Section 8: 7 Representative vehicle case-study archetypes (Small Petrol Hatchback, Diesel Car/SUV, CNG Car, Full Hybrid HEV, Plug-in Hybrid PHEV, Battery Electric BEV, Hydrogen FCEV)",
    "Section 9: 14 Public research sources registered with full URLs, publishers, years, and extraction status"
  ],
  "flagged_items_for_human_review": [
    {
      "record_id": "PROC-PAINTING / PROC-WELDING / PROC-HVAC-LIGHTING / PROC-HEATING / PROC-COMPRESSED-AIR / PROC-MAT-HANDLING",
      "issue": "Allocated facility services in PMC10890010 Table 4 (e.g. Painting = 4,167 MJ & 268 kg CO2/kg processed; Welding = 920 MJ & 62 kg CO2/kg processed)",
      "action_taken": "Flagged with is_allocated_facility_service = 1 and blocked from indiscriminate multiplication by total vehicle mass in the calculator."
    },
    {
      "record_id": "PROC-MOULDING-MISSING",
      "issue": "Polymer injection moulding is omitted from PMC10890010 Table 4",
      "action_taken": "Registered as an explicit data gap; generic machining factor is NOT substituted."
    },
    {
      "record_id": "MAT-LIB-PACK",
      "issue": "Section 2 does not give a single per-kg factor for Li-ion batteries",
      "action_taken": "Registered as requiring chemistry- and pack-specific kWh factor (BatPaC 5.2 / GREET 2025)."
    },
    {
      "record_id": "NRG-GRID-INDIA-CEA & Fuel Factors",
      "issue": "Section 5 provides definitions and source links (CEA Baseline Database) rather than a single static number for Indian grid electricity, petrol, diesel, and CNG",
      "action_taken": "Registered with null static factor and explicit provenance requiring versioned CEA/government dataset import or user-specified scenario parameter."
    }
  ]
}', '2026-10-19 07:48:34');

CREATE TABLE logistics_factors (
      mode_id TEXT PRIMARY KEY,
      transport_mode TEXT NOT NULL,
      vehicle_or_ship_class TEXT NOT NULL,
      fuel_or_traction TEXT NOT NULL,
      distance_km REAL,
      freight_mass_tonnes REAL,
      load_factor_pct REAL,
      empty_running_notes TEXT,
      factor_kgco2e_per_tonne_km REAL,
      factor_min REAL,
      factor_max REAL,
      unit TEXT NOT NULL DEFAULT 'kg CO2e/tonne-km',
      geography TEXT NOT NULL,
      reference_year INTEGER,
      system_boundary TEXT NOT NULL,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      data_quality_status TEXT NOT NULL,
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

INSERT INTO logistics_factors (mode_id, transport_mode, vehicle_or_ship_class, fuel_or_traction, distance_km, freight_mass_tonnes, load_factor_pct, empty_running_notes, factor_kgco2e_per_tonne_km, factor_min, factor_max, unit, geography, reference_year, system_boundary, source_id, data_quality_status, notes, created_at) VALUES ('LOG-ROAD-FREIGHT', 'Road freight', 'Heavy/Medium Commercial Truck (specify GVW class)', 'Diesel / CNG / LNG', NULL, NULL, NULL, 'Must record load factor and empty running share', NULL, NULL, NULL, 'kg CO2e/tonne-km', 'India', 2026, 'Well-to-Wheel Freight Transport', 'SRC-PACK-2026', 'Schema Layer Defined — Awaiting India Freight Factor Import', 'Section 6: Required data: kg CO2e/tonne-km; vehicle class, fuel, load factor, empty running.', '2026-10-19 07:48:34');
INSERT INTO logistics_factors (mode_id, transport_mode, vehicle_or_ship_class, fuel_or_traction, distance_km, freight_mass_tonnes, load_factor_pct, empty_running_notes, factor_kgco2e_per_tonne_km, factor_min, factor_max, unit, geography, reference_year, system_boundary, source_id, data_quality_status, notes, created_at) VALUES ('LOG-RAIL-FREIGHT', 'Rail freight', 'Indian Railways Freight Corridor / Rake', 'Electric Traction (Grid factor) / Diesel Locomotive', NULL, NULL, NULL, 'Specify traction split and empty return ratio', NULL, NULL, NULL, 'kg CO2e/tonne-km', 'India', 2026, 'Well-to-Wheel Freight Transport', 'SRC-PACK-2026', 'Schema Layer Defined — Awaiting India Freight Factor Import', 'Section 6: Required data: kg CO2e/tonne-km; traction electricity/diesel and grid/fuel factor.', '2026-10-19 07:48:34');
INSERT INTO logistics_factors (mode_id, transport_mode, vehicle_or_ship_class, fuel_or_traction, distance_km, freight_mass_tonnes, load_factor_pct, empty_running_notes, factor_kgco2e_per_tonne_km, factor_min, factor_max, unit, geography, reference_year, system_boundary, source_id, data_quality_status, notes, created_at) VALUES ('LOG-COASTAL-SHIP', 'Coastal shipping', 'Ro-Ro / Bulk / Container Coastal Vessel', 'Heavy Fuel Oil (HFO) / Marine Gas Oil (MGO)', NULL, NULL, NULL, 'Specify vessel utilisation %', NULL, NULL, NULL, 'kg CO2e/tonne-km', 'India Coastal / International Maritime', 2026, 'Well-to-Wheel Freight Transport', 'SRC-PACK-2026', 'Schema Layer Defined — Awaiting Maritime Factor Import', 'Section 6: Required data: kg CO2e/tonne-km; ship class, fuel, utilisation.', '2026-10-19 07:48:34');
INSERT INTO logistics_factors (mode_id, transport_mode, vehicle_or_ship_class, fuel_or_traction, distance_km, freight_mass_tonnes, load_factor_pct, empty_running_notes, factor_kgco2e_per_tonne_km, factor_min, factor_max, unit, geography, reference_year, system_boundary, source_id, data_quality_status, notes, created_at) VALUES ('LOG-SUPPLIER-PLANT', 'Supplier-to-plant transport (Inbound/Outbound Logistics)', 'Multi-modal (Road + Rail + Coastal)', 'Mode-specific', NULL, NULL, NULL, 'Avoid double counting logistics already included in supplier cradle-to-gate datasets', NULL, NULL, NULL, 'kg CO2e/tonne-km', 'India', 2026, 'Inbound/Outbound within Declared Boundary', 'SRC-PACK-2026', 'Calculation Rule Layer (E_transport = mass_t × km × factor)', 'Section 6: Include only flows within declared system boundary; avoid double counting logistics already included in supplier datasets.', '2026-10-19 07:48:34');

CREATE TABLE materials (
      material_id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      category TEXT NOT NULL,
      grade_or_type TEXT,
      production_route TEXT NOT NULL,
      primary_or_recycled TEXT NOT NULL CHECK(primary_or_recycled IN ('Primary', 'Recycled/Secondary', 'Mixed/Unspecified', 'Pack/Assembly')),
      recycled_content_pct REAL,
      factor_value REAL,
      factor_min REAL,
      factor_max REAL,
      unit TEXT NOT NULL,
      geography TEXT NOT NULL,
      reference_year INTEGER,
      system_boundary TEXT NOT NULL,
      uncertainty_or_range TEXT,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      data_quality_status TEXT NOT NULL,
      notes_and_limitations TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-STEEL-INDIA-BF', 'Primary Hot-Rolled Automotive Steel (India BF-BOF)', 'Ferrous Metals', 'IS 2062 / Auto Grade', 'Integrated Blast Furnace - Basic Oxygen Furnace', 'Primary', 0, 2.45, 2.2, 2.7, 'kg CO2e/kg', 'India', 2024, 'Cradle-to-Gate', '±10% plant variation', 'SRC-CEEW-AUTO', 'Peer-Reviewed Published', 'India BF-BOF route steel emission factor imported via CSV pipeline', '2026-10-18 13:04:03');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-STEEL-AUTO', 'Carbon steel / automotive steel', 'Ferrous Metals', 'Automotive rolled/stamped sheet & structural steel', 'BF-BOF (Primary) vs Scrap/EAF (Recycled) Screening Band', 'Mixed/Unspecified', NULL, NULL, 1.5, 2.8, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~1.5–2.8 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Primary steel vs recycled/EAF route changes result substantially. Store range and source rather than false-precision single value.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-CAST-IRON', 'Cast iron', 'Ferrous Metals', 'Automotive grey/ductile cast iron (engine blocks, rotors)', 'Cupola / Induction Melting Iron Production', 'Mixed/Unspecified', NULL, NULL, 1.5, 2.5, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~1.5–2.5 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Separate iron production from casting energy (e.g., 32.0 MJ/kg in Section 4) if source does so to avoid double counting.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-ALU-PRIMARY', 'Aluminium, primary', 'Non-Ferrous Metals', 'Primary ingot (wrought & cast automotive alloys)', 'Bayer Alumina + Hall-Heroult Electrolysis (Primary)', 'Primary', 0, NULL, 8, 18, 'kg CO2e/kg', 'Global Literature Screening Band (Grid-Dependent)', 2026, 'Cradle-to-Gate', '~8–18 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Electricity mix is a major driver (coal-heavy grids sit near upper bound); primary vs recycled aluminium must be kept separate.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-ALU-RECYCLED', 'Aluminium, recycled/secondary', 'Non-Ferrous Metals', 'Secondary remelted aluminium alloy', 'Scrap Collection + Remelting / Refining (Secondary)', 'Recycled/Secondary', 100, NULL, 0.5, 2.5, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~0.5–2.5 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Indicative only; scrap allocation method (cut-off vs avoided burden) and remelting route matter significantly.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-COPPER', 'Copper', 'Non-Ferrous Metals', 'Electrolytic tough pitch / wiring & motor winding copper', 'Pyrometallurgical / Hydrometallurgical Refining', 'Mixed/Unspecified', NULL, NULL, 2.5, 6, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~2.5–6 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Ore grade, smelting electricity carbon intensity, and recycled content matter.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-PLASTICS-MIXED', 'Plastics (mixed automotive polymers)', 'Polymers & Elastomers', 'Average automotive polymer mix (PP, ABS, PA, PVC, PU)', 'Petrochemical Polymerization & Compounding', 'Primary', NULL, NULL, 2, 5, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~2–5 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Do not use a single factor for all polymers if PP, ABS, PA, PVC etc. can be distinguished in detailed BOM.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-RUBBER-TYRE', 'Rubber / tyre compounds', 'Polymers & Elastomers', 'Natural & synthetic rubber (SBR/BR) with carbon black', 'Synthetic/Natural Rubber Production & Compounding', 'Primary', NULL, NULL, 2, 4, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~2–4 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Natural/synthetic rubber production and tyre vulcanisation/manufacturing are distinct modules.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-GLASS-AUTO', 'Flat glass / automotive glass', 'Ceramics & Glass', 'Tempered & laminated automotive glazing', 'Float Glass Process', 'Mixed/Unspecified', NULL, NULL, 0.8, 1.8, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~0.8–1.8 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Glass production and glass pane forming (16.0 MJ/kg in Section 4) may be separate in inventories.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-MAGNESIUM', 'Magnesium alloy', 'Non-Ferrous Metals', 'Automotive die-cast magnesium (AZ91D / AM60B)', 'Pidgeon Thermal Reduction / Electrolytic Process', 'Primary', NULL, NULL, 15, 35, 'kg CO2e/kg', 'Global Literature Screening Band', 2026, 'Cradle-to-Gate', '~15–35 kg CO2e/kg (Screening Range)', 'SRC-PACK-2026', 'Indicative Screening Range', 'Route and electricity sensitive (Pidgeon process vs electrolytic); usually small mass share (1–5 kg per vehicle).', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-LIB-PACK', 'Lithium-ion battery materials / pack', 'Battery Materials & Systems', 'Traction battery cells & pack (LFP, NMC, etc.)', 'Cathode, Anode, Electrolyte, Casing, Pack & Assembly', 'Pack/Assembly', NULL, NULL, NULL, NULL, 'kg CO2e/kWh (chemistry-specific)', 'Global / Study-Specific', 2025, 'Cradle-to-Gate Pack', 'Use chemistry- and pack-specific source; commonly modelled per kWh', 'SRC-GREET-BAT-2025', 'Needs Chemistry-Specific Source', 'Do not treat lithium carbonate factor as whole-battery factor; separate cathode, anode, electrolyte, casing, pack and assembly.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-MANGANESE', 'Manganese (alloying / battery element)', 'Ferrous & Battery Metals', 'Ferromanganese / alloying component in SWD(2023) 256', 'Submerged Arc Furnace Smelting', 'Primary', NULL, NULL, NULL, NULL, 'kg CO2e/kg', 'European Union (EU Average BOM)', 2023, 'Cradle-to-Gate', 'Mass reported in SWD(2023) 256 (7–8 kg/car); emission factor requires GREET/ecoinvent lookup', 'SRC-EC-SWD-2023-256', 'Mass Reported / Factor Needs Extraction', 'Included in EU SWD(2023) 256 representative vehicle composition (8 kg in ICEV/HEV/PHEV, 7 kg in BEV). No screening factor given in Section 2.', '2026-10-19 07:48:34');
INSERT INTO materials (material_id, name, category, grade_or_type, production_route, primary_or_recycled, recycled_content_pct, factor_value, factor_min, factor_max, unit, geography, reference_year, system_boundary, uncertainty_or_range, source_id, data_quality_status, notes_and_limitations, created_at) VALUES ('MAT-GFRP', 'Glass-fibre reinforced plastic (GFRP)', 'Composites', 'Structural / semi-structural automotive GFRP composite', 'Glass Fibre Drawing + Polymer Matrix Moulding', 'Primary', 0, NULL, NULL, NULL, 'kg CO2e/kg', 'European Union (EU Average BOM)', 2023, 'Cradle-to-Gate', 'Mass reported in SWD(2023) 256 (4–9 kg/car); use composite-specific factor or polymer screening proxy with flag', 'SRC-EC-SWD-2023-256', 'Mass Reported / Factor Needs Extraction', 'Reported in EU SWD(2023) 256 Table (9 kg ICEV, 4 kg HEV, 5 kg PHEV, 5 kg BEV).', '2026-10-19 07:48:34');

CREATE TABLE processes (
      process_id TEXT PRIMARY KEY,
      process_name TEXT NOT NULL,
      process_category TEXT NOT NULL,
      applicability TEXT NOT NULL,
      energy_consumption_mj REAL,
      process_emissions_kgco2e REAL,
      reference_unit TEXT NOT NULL,
      energy_source TEXT NOT NULL,
      geography TEXT NOT NULL,
      reference_year INTEGER,
      system_boundary TEXT NOT NULL,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      data_quality_status TEXT NOT NULL,
      is_allocated_facility_service INTEGER NOT NULL DEFAULT 0,
      limitations TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-STAMPING', 'Stamping', 'Metal Forming', 'Steel & aluminium sheet metal body panels / BIW', 5.1, 0.31, 'kg processed', 'Electricity / Plant Energy Mix (GREET reference)', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Apply only to stamped sheet mass (not total vehicle mass). Reproduced from 1,532 kg reference passenger car study.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-ALU-CASTING', 'Aluminium shape casting', 'Casting & Foundry', 'Cast aluminium components (engine head, housing, structural castings)', 55.3, 3.08, 'kg processed', 'Natural Gas / Electricity Foundry Mix', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Apply only to cast aluminium mass (e.g., 77–93 kg in SWD 2023/256). Ensure primary/secondary aluminium material factor does not already include shape casting.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-IRON-CASTING', 'Iron casting / iron process', 'Casting & Foundry', 'Cast iron components (engine block, brake discs, drums)', 32, 1.69, 'kg processed', 'Coke / Natural Gas / Electricity Foundry Mix', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Separate iron production from casting energy if source does so. Apply only to cast iron mass (16–101 kg).', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-CU-WIRE', 'Copper wire production', 'Wire Drawing & Forming', 'Copper wiring harnesses, motor windings, cables', 7.1, 0.43, 'kg processed', 'Electricity / Thermal Process Energy', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Apply only to drawn copper wire mass (14–35 kg per car).', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-BRASS-SCRAP', 'Brass from scrap', 'Secondary Metallurgy', 'Brass connectors, valves, radiator/thermal fittings', 7.4, 0.42, 'kg processed', 'Furnace Energy Mix', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Secondary brass remelting process factor per kg processed.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-SEC-LEAD', 'Secondary lead production', 'Secondary Metallurgy', '12V auxiliary lead-acid starter/buffer battery', 8.5, 0.49, 'kg processed', 'Smelting / Refining Energy Mix', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Applicable to secondary lead in 12V lead-acid batteries (initial and replacement).', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-MACHINING', 'Machining', 'Machining & Finishing', 'Machined metal powertrain, chassis, and transmission parts', 2.015, 0.115, 'kg processed', 'Electricity', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Do NOT silently substitute this generic machining factor for polymer injection moulding.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-FORGING', 'Forging', 'Metal Forming', 'Forged steel crankshafts, gears, axles, suspension knuckles', 45.1, 2.61, 'kg processed', 'Natural Gas / Electricity', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Apply only to forged component mass, not total steel mass.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-GLASS-FORMING', 'Glass pane forming', 'Glass Processing', 'Automotive windshields, sidelites, backlites (21–26 kg/car)', 16, 0.93, 'kg processed', 'Electricity / Natural Gas Furnace', 'Global / US (GREET literature reference)', 2024, 'Gate-to-Gate Process', 'SRC-PMC10890010-2024', 'Peer-Reviewed Published (PMC10890010 Table 4)', 0, 'Glass production and forming may be separate in inventories; check whether flat glass factor already includes forming.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-WELDING', 'Welding', 'Body Shop & Joining (Allocated Facility Factor)', 'Body-in-White spot/laser welding (allocated per kg reference in study)', 920, 62, 'kg processed (Allocated Facility/Reference Unit — Inspect Before Use)', 'Electricity', 'Global / US (PMC10890010 1,532 kg car case)', 2024, 'Allocated Plant / Body Shop Service', 'SRC-PMC10890010-2024', 'Allocated Facility Factor — Use Cautiously', 1, 'CRITICAL WARNING: Very high value (920 MJ, 62 kg CO2/kg) represents allocated facility/weld-material basis in PMC10890010 Table 4, NOT per kg of total vehicle mass. Do NOT multiply by total vehicle mass. Prefer plant-level energy per vehicle or per body.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-PAINTING', 'Painting', 'Paint Shop (Allocated Facility Factor)', 'Vehicle body coating, e-coat, primer, topcoat, curing ovens', 4167, 268, 'kg processed (Allocated Facility/Paint Mass Unit — Inspect Before Use)', 'Natural Gas / Electricity', 'Global / US (PMC10890010 1,532 kg car case)', 2024, 'Allocated Plant / Paint Shop Service', 'SRC-PMC10890010-2024', 'Allocated Facility Factor — Use Cautiously', 1, 'CRITICAL WARNING: 4,167 MJ and 268 kg CO2/kg processed in Table 4 represent allocated paint-shop energy per kg of paint/coating or per vehicle allocation, NOT per kg of vehicle mass. Never multiply by 1,137 kg vehicle mass!', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-HVAC-LIGHTING', 'HVAC and lighting (allocated factory services)', 'Allocated Factory Overhead', 'Assembly plant HVAC, ventilation, and lighting overhead', 3335, 225, 'allocated unit (PMC10890010 Table 4)', 'Electricity / Natural Gas', 'Global / US (PMC10890010 1,532 kg car case)', 2024, 'Allocated Plant Service', 'SRC-PMC10890010-2024', 'Allocated Facility Factor — Use Cautiously', 1, 'CRITICAL WARNING: Represents allocated factory service energy/emissions (3,335 MJ / 225 kg CO2). Treat as per-vehicle allocated factory overhead or inspect original table before applying; do NOT multiply by vehicle mass.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-MAT-HANDLING', 'Material handling', 'Allocated Factory Overhead', 'In-plant conveyors, cranes, forklifts, automated guided vehicles', 690, 39.5, 'allocated unit (PMC10890010 Table 4)', 'Electricity / Plant Fuel', 'Global / US (PMC10890010 1,532 kg car case)', 2024, 'Allocated Plant Service', 'SRC-PMC10890010-2024', 'Allocated Facility Factor — Use Cautiously', 1, 'Allocated factory service value from PMC10890010 Table 4. Do NOT multiply by total vehicle mass.', '2026-10-19 07:48:34');
