INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-COMPRESSED-AIR', 'Compressed air', 'Allocated Factory Overhead', 'Pneumatic tools, actuators, blow-off, paint atomisation', 1380, 93, 'allocated unit (PMC10890010 Table 4)', 'Electricity', 'Global / US (PMC10890010 1,532 kg car case)', 2024, 'Allocated Plant Service', 'SRC-PMC10890010-2024', 'Allocated Facility Factor — Use Cautiously', 1, 'Allocated factory service value from PMC10890010 Table 4. Do NOT multiply by total vehicle mass.', '2026-10-19 07:48:34');
INSERT INTO processes (process_id, process_name, process_category, applicability, energy_consumption_mj, process_emissions_kgco2e, reference_unit, energy_source, geography, reference_year, system_boundary, source_id, data_quality_status, is_allocated_facility_service, limitations, created_at) VALUES ('PROC-MOULDING-MISSING', 'Polymer injection moulding (Data Gap / Not in Table 4)', 'Polymer Processing', 'Automotive plastics (129–166 kg/car: bumpers, dash, trim)', NULL, NULL, 'kg polymer moulded', 'Electricity', 'Requires Process-Specific Inventory', 2026, 'Gate-to-Gate Process', 'SRC-PACK-2026', 'Missing in Source Table — Requires External Inventory', 0, 'Section 4 explicit instruction: Moulding is not separately listed in Table 4. Use a process-specific inventory with polymer type, machine energy, part mass, cycle time and scrap rate; do NOT silently substitute the generic machining factor.', '2026-10-19 07:48:34');

CREATE TABLE sources (
      source_id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      publisher TEXT NOT NULL,
      publication_year INTEGER,
      url TEXT,
      accessed_on TEXT,
      page_table TEXT,
      geography TEXT NOT NULL,
      dataset_version TEXT,
      licence_access_notes TEXT,
      extraction_status TEXT NOT NULL DEFAULT 'Directly Extracted from PDF',
      notes TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );

INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-PACK-2026', 'Automotive Life-Cycle Assessment Reference Data Pack (Research snapshot: 18 October 2026)', 'Techfest IIT Bombay 2026-27 Challenge 2 / Green Auto India Reference Pack', 2026, 'local://Reference_Data_Pack_2026.pdf', '2026-10-18', 'Pages 1-5, Sections 1-11', 'India / Global / EU Reference', 'Snapshot 2026-10-18', 'Competition Reference Data Pack', 'Directly Extracted from PDF', 'Primary reference starter pack containing screening material ranges, EU SWD(2023) 256 vehicle composition, PMC10890010 process table, energy/hydrogen guidance, and 7 vehicle archetypes.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-EC-SWD-2023-256', 'European Commission Impact Assessment Working Document SWD(2023) 256 — Vehicle Composition Section (JRC-RMIS & Argonne GREET 2021)', 'European Commission / Joint Research Centre (JRC-RMIS)', 2023, 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52023SC0256', '2026-10-18', 'PDF Page 2, Section 3 Table (1,137 kg depolluted passenger car)', 'European Union (EU Average)', 'SWD(2023) 256 / GREET 2021', 'Public EU Legal Document', 'Directly Extracted from PDF', 'Published European end-of-life passenger-car composition dataset scaled to 1,137 kg after depollution across ICEV, HEV, PHEV, and BEV. Useful as a transparent representative baseline, not a BOM for a named current Indian model.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-PMC10890010-2024', 'Predicting Design Solutions with Scenarios Considering the Quality of Materials and Products Based on a Life Cycle Assessment (LCA)', 'Peer-Reviewed Open-Access Article (PMC10890010) citing GREET and literature', 2024, 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10890010/', '2026-10-18', 'PDF Page 2, Section 4, Table 4 (1,532 kg reference passenger car)', 'Global / US (GREET literature reference)', '2024 Publication Table 4', 'Open Access (PMC)', 'Directly Extracted from PDF', 'Reports process energy (MJ/kg processed) and CO2 emissions (kg CO2/kg processed). High values (e.g. painting, welding, HVAC) represent allocated facility energy/services per kg, not direct process-only emissions.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-IEA-H2-2024', 'Global Hydrogen Review 2024 — GHG emissions of hydrogen and its derivatives', 'International Energy Agency (IEA)', 2024, 'https://www.iea.org/reports/global-hydrogen-review-2024/ghg-emissions-of-hydrogen-and-its-derivatives', '2026-10-18', 'PDF Page 3, Section 5 Table', 'Global', '2024 Review', 'Public IEA Report', 'Directly Extracted from PDF', 'Provides global production emission ranges for hydrogen from unabated natural gas (10-12 kg CO2e/kg H2) and unabated coal (22-26 kg CO2e/kg H2). Not a universal India-specific value.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-CEA-INDIA', 'CEA CDM CO2 Baseline Database for the Indian Power Sector', 'Central Electricity Authority (CEA), Ministry of Power, Government of India', 2024, 'https://cea.nic.in/cdm-co2-baseline-database/?lang=en', '2026-10-18', 'PDF Page 3, Section 5 Table', 'India', 'CEA Baseline Database (requires fiscal year & margin specification)', 'Public Government of India Database', 'External Backbone Source — Requires Further Extraction', 'Referenced in Section 5 for Indian grid electricity (kg CO2/kWh or t CO2/MWh). Must record fiscal year and whether weighted-average, operating margin, or combined margin is used.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-UMICH-GREET-2012', 'Life Cycle Material Data Update for GREET Model', 'University of Michigan Center for Sustainable Systems (CSS)', 2012, 'https://css.umich.edu/publications/research-publications/life-cycle-material-data-update-greet-model', '2026-10-18', 'PDF Page 1 & Page 4, Section 2 & Section 9', 'United States / Global Literature', '2012 Update', 'Public Research Publication', 'External Backbone Source — Screening Ranges Extracted', 'Material production and transformation process inventory background cited for Section 2 screening ranges.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-MAMARIKAS-2026', 'Passenger-car material shares and region-adjusted LCA factors (Journal of Cleaner Production)', 'Mamarikas et al., Journal of Cleaner Production', 2026, 'https://www.sciencedirect.com/journal/journal-of-cleaner-production', '2026-10-18', 'PDF Page 2, Section 2', 'Multi-region / Global', '2026 Study', 'Academic Journal', 'External Backbone Source — Screening Ranges Extracted', 'Cited alongside GREET in Section 2 for passenger-car material shares and region-adjusted screening factors.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-NATURE-INDIA-2022', 'India passenger-vehicle LCA (600+ vehicles; FY 2018/19) — Life-cycle assessment of Indian passenger vehicles', 'Nature Communications (s41467-022-29620-x) / PMC9018792', 2022, 'https://www.nature.com/articles/s41467-022-29620-x', '2026-10-18', 'PDF Page 4, Section 9 (Also Open Full Text: https://pmc.ncbi.nlm.nih.gov/articles/PMC9018792/)', 'India', 'FY 2018/19 Sample (600+ vehicles)', 'Open Access (CC BY)', 'External Backbone Source — Requires Further Extraction', 'India-specific life-cycle model covering energy production, vehicle use, vehicle production including EV batteries, and end-of-life recycling. Historical FY 2018/19 reference.', '2026-10-19 07:48:34');
INSERT INTO sources (source_id, title, publisher, publication_year, url, accessed_on, page_table, geography, dataset_version, licence_access_notes, extraction_status, notes, created_at) VALUES ('SRC-GREET-2025', 'Argonne GREET R&D Model 2025 Rev.1', 'Argonne National Laboratory (ANL)', 2025, 'https://greet.anl.gov/', '2026-10-18', 'PDF Page 4, Section 9', 'United States / Configurable', '2025 Rev.1', 'Publicly available model; inspect licence/version', 'External Backbone Source — Requires Further Extraction', 'Fuel-cycle and vehicle-cycle models used as methodological and inventory backbone.', '2026-10-19 07:48:34');
