CREATE TABLE use_phase_profiles (
      profile_id TEXT PRIMARY KEY,
      profile_name TEXT NOT NULL,
      applicable_powertrain TEXT NOT NULL,
      lifetime_distance_km REAL NOT NULL,
      annual_distance_km REAL NOT NULL,
      fuel_economy_value REAL,
      fuel_economy_unit TEXT,
      electricity_consumption_kwh_per_km REAL,
      electric_utility_factor REAL,
      maintenance_assumptions TEXT NOT NULL,
      replacement_parts_notes TEXT NOT NULL,
      operating_conditions TEXT NOT NULL,
      maintenance_emissions_kgco2e REAL,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      data_quality_status TEXT NOT NULL
    );

INSERT INTO use_phase_profiles (profile_id, profile_name, applicable_powertrain, lifetime_distance_km, annual_distance_km, fuel_economy_value, fuel_economy_unit, electricity_consumption_kwh_per_km, electric_utility_factor, maintenance_assumptions, replacement_parts_notes, operating_conditions, maintenance_emissions_kgco2e, source_id, data_quality_status) VALUES ('USE-STD-150K-ICE', 'Standard Passenger Car Functional Unit — ICE/CNG (150,000 km)', 'Petrol (ICEV) / Diesel (ICEV) / CNG', 150000, 12500, NULL, 'km/L or km/kg (User/Model Input)', NULL, 0, 'Formula: lifetime_distance_km ÷ fuel_economy × fuel_factor. Separate tailpipe combustion from upstream fuel production.', 'Include tyres, 12V lead-acid battery, engine oil/fluids, replacement parts and AC refrigerant leakage where data and boundaries support inclusion.', 'Indian urban/highway mixed cycle; state whether ARAI/MIDC test-cycle or real-world on-road consumption is used.', NULL, 'SRC-PACK-2026', 'Reference Functional Unit & Methodological Rule (Sections 1 & 7)');
INSERT INTO use_phase_profiles (profile_id, profile_name, applicable_powertrain, lifetime_distance_km, annual_distance_km, fuel_economy_value, fuel_economy_unit, electricity_consumption_kwh_per_km, electric_utility_factor, maintenance_assumptions, replacement_parts_notes, operating_conditions, maintenance_emissions_kgco2e, source_id, data_quality_status) VALUES ('USE-STD-150K-BEV', 'Standard Passenger Car Functional Unit — BEV (150,000 km)', 'Battery Electric (BEV)', 150000, 12500, NULL, 'N/A', NULL, 1, 'Formula: lifetime_distance_km × electricity_consumption (kWh/km) × grid_factor (kg CO2e/kWh). Include charging losses if wall-to-wheel.', 'Tyres, 12V auxiliary lead-acid battery, cabin filter, coolant/brake fluid, refrigerant leakage. Verify if traction battery replacement occurs within 150,000 km.', 'Use real-world or test-cycle data consistently and record which it is (HVAC load in Indian summer affects real-world Wh/km).', NULL, 'SRC-PACK-2026', 'Reference Functional Unit & Methodological Rule (Sections 1 & 7)');
INSERT INTO use_phase_profiles (profile_id, profile_name, applicable_powertrain, lifetime_distance_km, annual_distance_km, fuel_economy_value, fuel_economy_unit, electricity_consumption_kwh_per_km, electric_utility_factor, maintenance_assumptions, replacement_parts_notes, operating_conditions, maintenance_emissions_kgco2e, source_id, data_quality_status) VALUES ('USE-STD-150K-PHEV', 'Standard Passenger Car Functional Unit — HEV/PHEV (150,000 km)', 'Full Hybrid (HEV) / Plug-in Hybrid (PHEV)', 150000, 12500, NULL, 'km/L (Combustion Share)', NULL, 0.5, 'Model electric kilometres (lifetime_km × UF) and combustion kilometres (lifetime_km × (1 - UF)) separately.', 'Tyres, 12V battery, engine fluids, brake pads (reduced wear due to regen braking).', 'PHEV results depend strongly on electric utility factor (UF) and user charging behaviour.', NULL, 'SRC-PACK-2026', 'Reference Functional Unit & Methodological Rule (Sections 1 & 7)');

CREATE TABLE vehicle_lca_results (
      result_id TEXT PRIMARY KEY,
      scenario_name TEXT NOT NULL,
      vehicle_id TEXT REFERENCES vehicles(vehicle_id),
      functional_unit TEXT NOT NULL,
      lifetime_km REAL NOT NULL,
      material_production_kgco2e REAL NOT NULL,
      component_manufacturing_kgco2e REAL NOT NULL,
      manufacturing_total_kgco2e REAL NOT NULL,
      transport_kgco2e REAL NOT NULL,
      use_phase_tailpipe_kgco2e REAL NOT NULL,
      use_phase_upstream_kgco2e REAL NOT NULL,
      use_phase_total_kgco2e REAL NOT NULL,
      maintenance_kgco2e REAL NOT NULL,
      end_of_life_kgco2e REAL NOT NULL,
      total_kgco2e REAL NOT NULL,
      g_co2e_per_km REAL NOT NULL,
      double_counting_guard_applied INTEGER NOT NULL DEFAULT 1,
      assumptions_json TEXT NOT NULL,
      uncertainty_and_flags_json TEXT NOT NULL,
      data_quality_status TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now'))
    );

