ol_recycling_credit_kgco2e":0}', '{"run_id":"CS-RUN-1792328708682","engine_version":"GreenAutoIndia-LCA-Engine-v1.2.0","ranges":{"material_production":{"point":3555.57,"min":2290.01,"max":4821.15},"battery_pack_production":{"point":0,"min":0,"max":0},"component_and_process_manufacturing":{"point":1768.75,"min":1768.75,"max":1768.75},"manufacturing_total":{"point":5324.33,"min":4058.76,"max":6589.9},"logistics_and_transport":{"point":0,"min":0,"max":0},"use_phase_tailpipe":{"point":15865.38,"min":15865.38,"max":15865.38},"use_phase_upstream":{"point":4903.85,"min":4413.46,"max":5394.23},"use_phase_total":{"point":20769.23,"min":20278.85,"max":21259.62},"maintenance":{"point":480,"min":480,"max":480},"end_of_life_net":{"point":180,"min":180,"max":180}},"totals_range":{"total_kgco2e":{"point":26753.56,"min":24997.61,"max":28509.51},"g_co2e_per_km":{"point":178.36,"min":166.65,"max":190.06}},"comparison_vs_reference":{"reference_code":"ICEV","diff_kgco2e_point":-2462.07,"diff_pct_point":-8.43,"diff_pct_min":-9.15,"diff_pct_max":-7.78,"break_even_km_vs_reference":9639},"warnings":["Material \"Manganese\" (8 kg) has no emission factor in the Reference Data Pack (e.g. Manganese, GFRP, or Other). Excluded from material sum and flagged.","Material \"Glass-fibre reinforced plastic\" (9 kg) has no emission factor in the Reference Data Pack (e.g. Manganese, GFRP, or Other). Excluded from material sum and flagged.","Material \"Other\" (5 kg) has no emission factor in the Reference Data Pack (e.g. Manganese, GFRP, or Other). Excluded from material sum and flagged.","Transportation & Logistics stage (Section 6) is set to 0 kg CO2e because the Reference Data Pack defines the schema layer (Road, Rail, Coastal Shipping in kg CO2e/tonne-km) without an inline India freight emission factor table. Enable optional logistics scenario parameters if needed.","Polymer injection moulding (129–166 kg plastics/car) is excluded from gate-to-gate process emissions because Section 4 (PMC10890010 Table 4) omits injection moulding and instructs not to substitute generic metal machining."]}', 'Modelled Scenario (Using Screening Ranges & User Inputs)', '2026-10-18 13:05:08');

CREATE TABLE vehicles (
      vehicle_id TEXT PRIMARY KEY,
      manufacturer TEXT NOT NULL,
      model TEXT NOT NULL,
      variant TEXT NOT NULL,
      model_year INTEGER,
      powertrain TEXT NOT NULL CHECK(powertrain IN ('Petrol (ICEV)', 'Diesel (ICEV)', 'CNG', 'Full Hybrid (HEV)', 'Plug-in Hybrid (PHEV)', 'Battery Electric (BEV)', 'Hydrogen Fuel Cell (FCEV)')),
      body_type TEXT NOT NULL,
      kerb_mass_kg REAL,
      glider_reference_mass_kg REAL,
      fuel_consumption_value REAL,
      fuel_consumption_unit TEXT,
      electricity_consumption_kwh_per_km REAL,
      electric_utility_factor REAL,
      battery_capacity_kwh REAL,
      battery_chemistry TEXT,
      range_km REAL,
      test_cycle TEXT,
      material_coverage_notes TEXT,
      public_data_to_collect TEXT,
      manufacturing_emissions_approach TEXT,
      source_id TEXT NOT NULL REFERENCES sources(source_id),
      source_url TEXT,
      lca_data_status TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now'))
    );

INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-1-PETROL', 'Representative Archetype (India LCA Reference)', '1. Small Petrol Hatchback (ICEV)', 'Standard Petrol Manual/AMT Baseline Archetype', 2026, 'Petrol (ICEV)', 'Small Hatchback', 1137, 1137, NULL, 'km/L (Collect official Indian model MIDC/WLTP value)', NULL, 0, NULL, 'No traction battery (12V lead-acid auxiliary only)', NULL, 'Record whether MIDC / ARAI or Real-World', 'Steel (653 kg), cast iron (101 kg), wrought aluminium (40 kg), cast aluminium (79 kg), plastics (159 kg), glass (24 kg), copper (14 kg), rubber (41 kg); no traction battery.', 'Use official Indian model fuel economy and curb mass; use representative ICEV BOM (SWD 2023/256) only as labelled proxy.', 'Materials + component manufacturing + assembly factor from selected LCA model.', 'SRC-PACK-2026', 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52023SC0256', 'Representative Published Archetype (Proxy BOM)', '2026-10-19 07:48:34');
INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-2-DIESEL', 'Representative Archetype (India LCA Reference)', '2. Diesel Passenger Car / Compact SUV (ICEV)', 'Standard Diesel Compression-Ignition Baseline Archetype', 2026, 'Diesel (ICEV)', 'Passenger Car / Compact SUV', 1137, 1137, NULL, 'km/L (Collect official variant-specific value)', NULL, 0, NULL, 'No traction battery (12V lead-acid auxiliary only)', NULL, 'Record whether MIDC / ARAI or Real-World', 'Similar glider to ICEV (1,137 kg baseline); heavier diesel engine block, turbocharger, and exhaust/emissions-control system (DOC/DPF/SCR).', 'Variant-specific mass and fuel consumption from official source.', 'Same manufacturing method as ICEV; separate engine/powertrain inventory if available.', 'SRC-PACK-2026', 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52023SC0256', 'Representative Published Archetype (Proxy BOM)', '2026-10-19 07:48:34');
INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-3-CNG', 'Representative Archetype (India LCA Reference)', '3. CNG Passenger Car', 'Factory-Fitted Bi-Fuel CNG Baseline Archetype', 2026, 'CNG', 'Hatchback / Sedan', 1197, 1137, NULL, 'km/kg CNG (Collect official Indian model value)', NULL, 0, NULL, 'No traction battery', NULL, 'Record whether MIDC / ARAI or Real-World', 'ICE glider (1,137 kg baseline) plus high-pressure steel/composite CNG storage cylinder (~50–65 kg) and pressure regulator/fuel system.', 'Official CNG kerb mass/fuel economy; cylinder material/weight where disclosed.', 'Manufacturing plus CNG cylinder/system proxy; use CNG well-to-wheel factor including methane leakage.', 'SRC-PACK-2026', 'https://www.nature.com/articles/s41467-022-29620-x', 'Representative Published Archetype (Proxy BOM)', '2026-10-19 07:48:34');
INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-4-HEV', 'Representative Archetype (India LCA Reference)', '4. Full Hybrid Electric Vehicle (HEV)', 'Strong / Series-Parallel Hybrid Baseline Archetype', 2026, 'Full Hybrid (HEV)', 'Sedan / Mid-size SUV', 1137, 1137, NULL, 'km/L (Collect official Indian HEV fuel economy)', 0, 0, 1.5, 'Small HEV buffer pack (~0.8–2.0 kWh NiMH or Li-ion; often undisclosed for exact retail model)', NULL, 'Record whether MIDC / ARAI or Real-World', 'EU SWD(2023) 256 HEV BOM: Steel (660 kg), Cast iron (101 kg), Wrought Al (58 kg), Cast Al (91 kg), Copper (20 kg), Plastics (129 kg) plus small traction motor, inverter and buffer battery.', 'Representative HEV BOM; exact retail-model battery chemistry/mass may be undisclosed.', 'Vehicle-cycle study/GREET HEV case; do NOT use full BEV battery factor.', 'SRC-EC-SWD-2023-256', 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52023SC0256', 'Representative Published Archetype (EU SWD 2023/256 BOM)', '2026-10-19 07:48:34');
INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-5-PHEV', 'Representative Archetype (India LCA Reference)', '5. Plug-in Hybrid Electric Vehicle (PHEV)', 'Dual-Mode Grid-Charged Hybrid Baseline Archetype', 2026, 'Plug-in Hybrid (PHEV)', 'Crossover / SUV', 1137, 1137, NULL, 'km/L (Charge-sustaining combustion mode)', NULL, 0.5, 14, 'Mid-size Li-ion traction pack (NMC / LFP)', NULL, 'Requires Electric Utility Factor (UF) & charging behaviour specification', 'EU SWD(2023) 256 PHEV BOM: Steel (621 kg), Cast iron (96 kg), Wrought Al (76 kg), Cast Al (93 kg), Copper (23 kg), Plastics (143 kg) plus traction battery and onboard charging electronics.', 'Use published PHEV inventory and electric utility factor (share of km driven on grid electricity vs petrol).', 'Manufacturing + split electric/fuel use phase.', 'SRC-EC-SWD-2023-256', 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52023SC0256', 'Representative Published Archetype (EU SWD 2023/256 BOM)', '2026-10-19 07:48:34');
INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-6-BEV', 'Representative Archetype (India LCA Reference)', '6. Battery Electric Vehicle (BEV)', 'Dedicated Battery Electric Passenger Car Archetype', 2026, 'Battery Electric (BEV)', 'Hatchback / Compact SUV', 1137, 1137, NULL, 'N/A (Zero Tailpipe Emissions)', NULL, 1, NULL, 'Use model battery capacity/chemistry only if public (e.g. LFP / NMC); otherwise use cited representative battery BOM (BatPaC 5.2)', NULL, 'Use real-world or test-cycle data consistently and record which it is', 'EU SWD(2023) 256 BEV BOM: Steel (642 kg), Cast iron (16 kg), Wrought Al (108 kg), Cast Al (77 kg), Copper (35 kg), Plastics (166 kg), Glass (26 kg), Rubber (39 kg) plus battery cells/pack, motor and power electronics.', 'Use model battery capacity/chemistry only if public; otherwise use cited representative battery BOM.', 'Include battery production and electricity use; model recycling explicitly.', 'SRC-EC-SWD-2023-256', 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52023SC0256', 'Representative Published Archetype (EU SWD 2023/256 BOM)', '2026-10-19 07:48:34');
INSERT INTO vehicles (vehicle_id, manufacturer, model, variant, model_year, powertrain, body_type, kerb_mass_kg, glider_reference_mass_kg, fuel_consumption_value, fuel_consumption_unit, electricity_consumption_kwh_per_km, electric_utility_factor, battery_capacity_kwh, battery_chemistry, range_km, test_cycle, material_coverage_notes, public_data_to_collect, manufacturing_emissions_approach, source_id, source_url, lca_data_status, created_at) VALUES ('VEH-ARCH-7-FCEV', 'Representative Archetype (India LCA Reference)', '7. Hydrogen Fuel-Cell Electric Vehicle (FCEV)', 'PEM Fuel-Cell & Carbon-Fibre H2 Tank Archetype', 2026, 'Hydrogen Fuel Cell (FCEV)', 'Sedan / Crossover', NULL, 1137, NULL, 'km/kg H2 (Published FCEV archetype)', NULL, 0, 1.5, 'High-power buffer battery + PEM Fuel Cell Stack + 700 bar Type IV CFRP H2 Tank', NULL, 'Published FCEV archetype cycle', 'Glider, electric motor, buffer battery, PEM fuel-cell stack (platinum catalyst), hydrogen storage tank (carbon-fibre composite).', 'Use published FCEV archetype; do NOT infer tank or stack mass from range.', 'Hydrogen pathway (SMR vs coal vs electrolytic) dominates use-phase sensitivity; include stack/tank production where data exist.', 'SRC-PACK-2026', 'https://greet.anl.gov/', 'Representative Published Archetype (Requires GREET FCEV Stack/Tank Inventory)', '2026-10-19 07:48:34');

COMMIT;
